"""Build a portable static restaurant demo using Python's standard library."""
from pathlib import Path
from html import escape as esc
import json, shutil
ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist'
MENU=json.loads((ROOT/'data/menu.json').read_text())
BOOK='https://www.opentable.com/restref/client/?rid=58273'
MAP='https://www.google.com/maps/search/?api=1&query=Aioli+Bodega+Espanola+1800+L+Street+Sacramento'
photos={
'paella':('aioli-cuisine-08a','Aioli’s seafood paella with mussels, shrimp and lemon',1024,734),
'lamb':('aioli-cuisine-05a','Grilled lamb chops and vegetables at Aioli',2500,1609),
'vegetables':('aioli-cuisine-06a','A plate of grilled seasonal vegetables',2361,1500),
'salad':('aioli-cuisine-07a','Fresh salad with citrus, olives and greens',1024,654),
'dessert':('aioli-cuisine-04a','Almond cake with cream and orange',1024,712),
'squid':('aioli-cuisine-02a','Aioli’s stuffed squid with sauce and herbs',1024,640),
'wine':('aioli-atmo-06a','Wine bottles in the bodega’s wooden wine shelves',848,566),
'ceramic':('aioli-atmo-03a','Painted Spanish ceramic pitcher and wine bottles at Aioli',721,1080),
'chandelier':('aioli-atmo-02a','Decorative metal chandelier inside Aioli',721,1080),
'sculpture':('aioli-atmo-07a','Sculpture displayed inside the bodega',721,1080)}
def photo(key,cls='',eager=False,sizes='(max-width: 700px) 100vw, 55vw'):
 name,alt,w,h=photos[key]
 widths=[480,960]+([1600] if w>960 else [])
 return f'<img class="{cls}" src="{{BASE}}assets/images/{name}-960.webp" srcset="'+', '.join(f'{{BASE}}assets/images/{name}-{x}.webp {min(x,w)}w' for x in widths)+f'" sizes="{sizes}" width="{w}" height="{h}" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def button(label,url,kind=''):
 return f'<a class="button {kind}" href="{url}">{label}</a>'
def head(title,base,desc):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Aioli Bodega Española</title><meta name="description" content="{desc}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#342336"><link rel="icon" href="{base}assets/images/aioli-logo.webp"><link rel="stylesheet" href="{base}assets/fonts/fonts.css"><link rel="stylesheet" href="{base}styles.css"><script defer src="{base}app.js"></script><noscript><style>.menu-controls{{display:none}}@media(max-width:767px){{.site-header{{height:auto;position:relative;flex-wrap:wrap;padding-top:12px}}.nav-toggle{{display:none}}.mobile-nav[hidden]{{display:flex!important;position:static;box-shadow:none;padding:10px 0 20px}}.mobile-nav a{{font-size:22px}}}}</style></noscript></head><body><a class="skip" href="#main">Skip to content</a>'''
def header(active=''):
 links=[('Our Menu','menu/'),('The Bodega','bodega/'),('Contact','visit/')]
 return '<header class="site-header"><a class="brand" href="{BASE}" aria-label="Aioli Bodega Española home"><img src="{BASE}assets/images/aioli-logo.webp" width="72" height="72" alt="Aioli"><span>Bodega<br>Española</span></a><nav class="desktop-nav" aria-label="Main navigation">'+''.join(f'<a href="{{BASE}}{url}"'+(' aria-current="page"' if url==active else '')+f'>{text}</a>' for text,url in links)+'</nav><a class="button header-book" href="{BASE}visit/#reservations">Reservations</a><button class="nav-toggle" aria-expanded="false" aria-controls="mobile-nav">Menu</button><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>'+''.join(f'<a href="{{BASE}}{url}">{text}</a>' for text,url in links)+'<a href="{BASE}visit/#reservations">Reservations</a></nav></header>'
def footer():
 return '''<footer class="footer"><div class="footer-top"><a class="footer-brand" href="{BASE}">Aioli<span>Bodega Española</span></a><p>Come for a plate.<br>Make an evening of it.</p><div><a href="https://www.instagram.com/aioli_bodega/" target="_blank" rel="noopener">Instagram</a><a href="https://www.facebook.com/aiolibodegaespanola/" target="_blank" rel="noopener">Facebook</a><a href="tel:+19164479440">916.447.9440</a></div></div><div class="footer-bottom"><span>1800 L Street, Sacramento, CA 95811</span><span>©2025 Reda Belalrbi &amp; Associates, Inc.</span><span>Website concept</span></div></footer><a class="mobile-book" href="{BASE}visit/#reservations">Reservations</a>'''
def visitblock():
 return f'''<section class="visit-block" id="contact-aioli"><div class="visit-title"><h2 id="aioli-contact">Meet us<br>on L Street.</h2><p>1800 L Street<br>Midtown Sacramento, CA 95811</p>{button('Get directions',MAP,'outline')}</div><div class="visit-details"><h3>A good time to come by</h3><dl><div><dt>Monday to Saturday</dt><dd>11 am – 10 pm</dd></div><div><dt>Sunday</dt><dd>3 pm – 9 pm</dd></div></dl><p>For a table, a question, or a special occasion,<br>give us a call.</p><a class="phone" href="tel:+19164479440">916.447.9440</a></div></section>'''
def sheets():
 sections=[('Chef Pablo’s seasonal selections',['aioli-chefs-choice-fall-2026-menu']),('Lunch',['aioli-lunch-fall-2026-menu-p1','aioli-lunch-fall-2026-menu-p2']),('Dessert & after-dinner drinks',['aioli-dessert-fall-2026-menu-p1','aioli-dessert-fall-2026-menu-p2']),('Wine, beer & cocktails',['aioli-wine-fall-2026-menu-p1','aioli-wine-fall-2026-menu-p2'])]
 return '<section class="printed-menus" id="original-menus"><h2>The original menus</h2><p>The full Fall 2026 menus, including every wine, spirit and after-dinner drink. Prices and availability may change.</p>'+''.join('<details><summary>'+title+'</summary><div class="sheet-grid">'+''.join(f'<a href="{{BASE}}assets/originals/{name}.png" target="_blank" rel="noopener"><img src="{{BASE}}assets/originals/{name}.png" loading="lazy" alt="{esc(title)} original menu, sheet {i+1}"><span>Open full-size sheet {i+1}</span></a>' for i,name in enumerate(files))+'</div></details>' for title,files in sections)+'</section>'
HOME='''<main id="main"><section class="hero" id="content"><div class="hero-copy"><h1>A little longer<br><em>at the table.</em></h1><div class="hero-bottom"><p>Spanish plates, a well-poured glass,<br>and an evening in Midtown Sacramento.</p>'''+button('Our Menu','{BASE}menu/')+'''</div></div><div class="hero-photo">'''+photo('paella',eager=True)+'''<div class="photo-caption"><span>Paella. Made to share.</span><span>Aioli Bodega Española</span></div></div><div class="hero-side">'''+photo('wine',eager=True,sizes='(max-width: 700px) 35vw, 20vw')+'''<span>1800 L Street<br>Sacramento</span></div></section>
<section class="intro"><h2>A few plates.<br>A lot to talk about.</h2><div><p>Start with tapas. Make room for paella. Finish with something sweet.</p><p>From Chef Pablo’s seasonal selections to a bottle from the bodega, there’s plenty to bring to the table.</p><a class="text-link" href="{BASE}bodega/">Step inside Aioli</a></div></section>
<section class="food-spread" aria-label="From Aioli’s kitchen"><figure class="food-main">'''+photo('lamb')+'''</figure><figure class="food-small">'''+photo('dessert')+'''</figure><p class="spread-word" aria-hidden="true">Buen<br><em>provecho.</em></p></section>
<section class="menu-invitation" id="aioli-menu"><h2>De la cocina<br><em>y del bar.</em></h2><div class="menu-links"><a href="{BASE}menu/#seasonal"><span>Chef Pablo’s selections</span><small>What’s in season</small></a><a href="{BASE}menu/#lunch"><span>Lunch</span><small>Tapas, paella & more</small></a><a href="{BASE}menu/#dessert"><span>Dessert</span><small>Something sweet</small></a><a href="{BASE}menu/#drinks"><span>Wine & cocktails</span><small>Find your glass</small></a></div></section>
<section class="bodega-feature"><div class="bodega-photo">'''+photo('ceramic')+'''</div><div class="bodega-copy"><h2>More than<br>what’s on<br><em>the plate.</em></h2><p>The wine shelves. The ceramics. The details you notice between courses. Take a look around the bodega.</p><a class="text-link" href="{BASE}bodega/">Explore the bodega</a></div>'''+photo('chandelier','bodega-detail')+'''</section>'''+visitblock()+'''</main>'''
def menu_page():
 out='''<main id="main"><section class="page-heading menu-heading"><h1>Bring your<br><em>appetite.</em></h1><p>From the first tapa to the last spoonful.<br>Explore the kitchen and the bar.</p></section><section class="menu-browser" aria-label="Restaurant menu"><div class="menu-controls"><div class="category-buttons" role="group" aria-label="Menu category"><button data-category="seasonal">Seasonal</button><button data-category="lunch">Lunch</button><button data-category="dessert">Dessert</button><button data-category="drinks">Drinks</button><button data-category="all">All</button></div><div class="menu-search"><label for="menu-search">Find a dish or ingredient</label><input type="search" id="menu-search" placeholder="Try paella, shrimp, chocolate…" autocomplete="off"></div></div><div class="menu-status"><p id="menu-status" role="status" aria-live="polite"></p><a href="#original-menus">View original menus</a></div><div class="empty-state" hidden><h2>No dishes found.</h2><p>Try a different ingredient or browse the full menu.</p><button class="button reset-menu">Show all dishes</button></div>'''
 for group in MENU:
  out+=f'<section class="menu-group" data-menu-category="{group["category"]}"><h2>{esc(group["title"])}</h2>'
  if group['note']:out+='<p class="group-note">'+esc(group['note'])+'</p>'
  out+='<div class="dish-grid">'
  for item in group['items']:
   price='$'+item['price'] if item['price'][0].isdigit() else item['price']
   out+=f'<article class="dish"><div><h3>{esc(item["name"])}</h3><span class="price">{price}</span></div><p>{esc(item["description"])}</p></article>'
  out+='</div></section>'
 out+='''<p class="menu-disclaimer">Please tell your server about allergies or dietary requirements. Consuming raw or undercooked meat or eggs may increase the chance of foodborne illness. A 20% gratuity is included on parties of six or more. See the original menus for the restaurant’s full notes.</p></section>'''+sheets()+'''<section class="small-cta"><h2>We’ll see you at the table.</h2>'''+button('Reservations','{BASE}visit/#reservations')+'</section></main>'
 return out
BODEGA='''<main id="main"><section class="page-heading"><h1>A place to<br><em>settle in.</em></h1><p>Good food. A glass of something.<br>The details that make it Aioli.</p></section><section class="gallery" aria-label="Photos of Aioli">'''+''.join(f'<figure class="gallery-{i}"><a class="gallery-open" href="{{BASE}}assets/images/{photos[k][0]}-960.webp" data-gallery="{i}" aria-label="Enlarge: {photos[k][1]}">{photo(k,sizes="(max-width:700px) 100vw, 50vw")}</a><figcaption>{label}</figcaption></figure>' for i,(k,label) in enumerate([('ceramic','A corner of the bodega'),('paella','Paella for the table'),('wine','Something from the cellar'),('lamb','From the grill'),('chandelier','Look a little closer'),('salad','Bright, fresh, full of flavor'),('sculpture','The character of Aioli'),('dessert','One last bite'),('vegetables','A seasonal plate'),('squid','From the kitchen')]))+'''</section><dialog class="lightbox" aria-label="Aioli photo gallery"><div class="lightbox-toolbar"><span class="gallery-count"></span><button class="close-lightbox">Close</button></div><img alt=""><div class="lightbox-bottom"><button class="prev-photo">Previous</button><p class="gallery-caption"></p><button class="next-photo">Next</button></div></dialog>'''+visitblock()+'''</main>'''
VISIT='''<main id="main"><section class="page-heading visit-heading"><h1>Find us<br><em>in Midtown.</em></h1><p>Find us at 1800 L Street,<br>in the heart of Midtown Sacramento.</p></section><section class="reservation-panel" id="reservations"><div><h2>Save a seat.</h2><p>Find your table through OpenTable.<br>For questions or special arrangements, call us.</p><div class="reservation-actions">'''+button('Reserve on OpenTable',BOOK)+button('Call 916.447.9440','tel:+19164479440','outline')+'''</div><p class="booking-note">You’ll continue to Aioli’s booking page on OpenTable.</p></div>'''+photo('paella')+'''</section>'''+visitblock()+'''<section class="sister-spots"><h2>In good company.</h2><p>Meet our sister spots in Sacramento.</p><div><a href="https://brasseriedumonde.com/" target="_blank" rel="noopener"><h3>Brasserie du Monde</h3><span>1201 K Street</span><span>Visit website</span></a><a href="https://thegrandwinebar.com/" target="_blank" rel="noopener"><h3>The Grand Wine Bar</h3><span>1600 L Street</span><span>Visit website</span></a></div></section></main>'''
NOTFOUND='''<main id="main" class="not-found"><h1>This table<br><em>is empty.</em></h1><p>We couldn’t find that page. Let’s get you back to the bodega.</p>'''+button('Back to Aioli','{BASE}')+'</main>'
pages=[('index.html','A little longer at the table','Spanish tapas, paella, wine and cocktails in Midtown Sacramento.',HOME,''),('menu/index.html','Our Menu','Browse Aioli’s seasonal selections, lunch, desserts and drinks, with the complete original menus.',menu_page(),'menu/'),('bodega/index.html','The Bodega','A look inside Aioli Bodega Española, its food, wine and dining-room details.',BODEGA,'bodega/'),('visit/index.html','Visit & Reservations','Reserve a table, find opening hours and get directions to Aioli Bodega Española in Sacramento.',VISIT,'visit/'),('404.html','Page not found','Return to Aioli Bodega Española.',NOTFOUND,'')]
DIST.mkdir(exist_ok=True)
for path,title,desc,body,active in pages:
 base='../' if '/' in path else './'
 html=(head(title,base,desc)+header(active)+body+footer()+'</body></html>').replace('{BASE}',base)
 for target in [ROOT/path,DIST/path]:target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)
for f in ['styles.css','app.js']:shutil.copy2(ROOT/f,DIST/f)
for d in ['assets','data']:shutil.copytree(ROOT/d,DIST/d,dirs_exist_ok=True)
for folder in [ROOT,DIST]:
 (folder/'.nojekyll').write_text('');(folder/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
print('Built five complete pages, 67 readable menu entries and seven original menu sheets.')
